// ── Authority consistency ──

describe("Manifest authority profiles are consistent with risk levels", () => {
  interface Authority {
    risk_level: string
    requires_approval: boolean
    requires_hash_precondition: boolean
    side_effects: string
  }

  const files: { name: string; auth: Authority }[] = []

  for (const name of ["struct_read.v1.json", "text_replace.v1.json", "batch_edit.v1.json"]) {
    const raw = readFileSync(resolve(MANIFESTS_DIR, name), "utf-8")
    const json = JSON.parse(raw) as { authority: Authority }
    files.push({ name, auth: json.authority })
  }

  it("read tool has no approval or hash precondition", () => {
    const sr = files.find((f) => f.name.startsWith("struct_read"))!
    expect(sr.auth.risk_level).toBe("read")
    expect(sr.auth.requires_approval).toBe(false)
    expect(sr.auth.requires_hash_precondition).toBe(false)
    expect(sr.auth.side_effects).toBe("filesystem_read")
  })

  it("write tools have approval and hash precondition", () => {
    const writes = files.filter((f) => f.name !== "struct_read.v1.json")
    for (const w of writes) {
      expect(w.auth.requires_approval).toBe(true)
      expect(w.auth.requires_hash_precondition).toBe(true)
      expect(w.auth.side_effects).toBe("filesystem_write")
    }
  })

  it("batch_edit has higher risk than text_replace", () => {
    const tr = files.find((f) => f.name.startsWith("text_replace"))!
    const be = files.find((f) => f.name.startsWith("batch_edit"))!
    // Risk ordering: write_low < write_medium < write_high
    const levels = ["write_low", "write_medium", "write_high"]
    const trIdx = levels.indexOf(tr.auth.risk_level)
    const beIdx = levels.indexOf(be.auth.risk_level)
    expect(trIdx).toBeGreaterThanOrEqual(0)
    expect(beIdx).toBeGreaterThanOrEqual(0)
    expect(beIdx).toBeGreaterThan(trIdx)
  })

  it("all manifests have valid risk_level", () => {
    const valid: string[] = ["read", "write_low", "write_medium", "write_high", "exec", "network", "memory_authority"]
    for (const f of files) {
      expect(valid).toContain(f.auth.risk_level)
    }
  })
})

import { describe, it, expect } from "bun:test"
import { resolveReadPath, resolveWritePath } from "../_lib/path-policy"
import { buildToolContext } from "../_lib/tool-context"
import type { PathPolicyDecisionV1, OmpToolContextV1 } from "../_lib/types"

function ctx(): OmpToolContextV1 {
  return buildToolContext({ cwd: "/tmp/test-repo" })
}

// ── helpers ──

function ok(result: PathPolicyDecisionV1): string {
  expect(result.ok).toBe(true)
  return result.normalized_path!
}

function denied(result: PathPolicyDecisionV1): string {
  expect(result.ok).toBe(false)
  return result.denied_pattern!
}

// ── resolveReadPath ──

describe("resolveReadPath", () => {
  it("resolves a normal repo-relative path", () => {
    const r = resolveReadPath("src/main.ts", ctx())
    expect(ok(r)).toBe("src/main.ts")
  })

  it("denies absolute path", () => {
    const r = resolveReadPath("/etc/passwd", ctx())
    expect(denied(r)).toBe("<absolute>")
  })

  it("denies parent traversal that escapes repo root", () => {
    const r = resolveReadPath("../outside/file.ts", ctx())
    expect(denied(r)).toBe("<escape>")
  })

  it("denies .env exact match", () => {
    const r = resolveReadPath(".env", ctx())
    expect(denied(r)).toBe(".env")
  })

  it("denies .env.* glob pattern", () => {
    const r = resolveReadPath(".env.production", ctx())
    expect(denied(r)).toBe(".env.*")
  })

  it("allows a normal nested path", () => {
    const r = resolveReadPath("packages/app/README.md", ctx())
    expect(ok(r)).toBe("packages/app/README.md")
  })

  it("allows .git/ directories for reads", () => {
    const r = resolveReadPath(".git/HEAD", ctx())
    expect(ok(r)).toBe(".git/HEAD")
  })

  it("allows node_modules/ for reads", () => {
    const r = resolveReadPath("node_modules/foo/index.js", ctx())
    expect(ok(r)).toBe("node_modules/foo/index.js")
  })
})

// ── resolveWritePath ──

describe("resolveWritePath", () => {
  it("resolves a normal repo-relative path", () => {
    const r = resolveWritePath("src/main.ts", ctx())
    expect(ok(r)).toBe("src/main.ts")
  })

  it("denies absolute path", () => {
    const r = resolveWritePath("/etc/passwd", ctx())
    expect(denied(r)).toBe("<absolute>")
  })

  it("denies parent traversal that escapes repo root", () => {
    const r = resolveWritePath("../outside/file.ts", ctx())
    expect(denied(r)).toBe("<escape>")
  })

  it("denies .git/ segment", () => {
    const r = resolveWritePath(".git/config", ctx())
    expect(denied(r)).toBe(".git/")
  })

  it("denies node_modules/ segment", () => {
    const r = resolveWritePath("node_modules/pkg/index.js", ctx())
    expect(denied(r)).toBe("node_modules/")
  })

  it("denies .env exact match", () => {
    const r = resolveWritePath(".env", ctx())
    expect(denied(r)).toBe(".env")
  })

  it("denies .env.production glob pattern", () => {
    const r = resolveWritePath(".env.production", ctx())
    expect(denied(r)).toBe(".env.*")
  })

  it("denies .omp/evidence/receipts/ artifact path", () => {
    const r = resolveWritePath(".omp/evidence/receipts/001-receipt.json", ctx())
    expect(denied(r)).toBe(".omp/evidence/receipts/")
  })

  it("denies .omp/evidence/diffs/ artifact path", () => {
    const r = resolveWritePath(".omp/evidence/diffs/001/diff.diff", ctx())
    expect(denied(r)).toBe(".omp/evidence/diffs/")
  })

  it("denies .omp/evidence/events/ artifact path", () => {
    const r = resolveWritePath(".omp/evidence/events/tool-events.jsonl", ctx())
    expect(denied(r)).toBe(".omp/evidence/events/")
  })

  it("denies .omp/evidence/journals/ artifact path", () => {
    const r = resolveWritePath(".omp/evidence/journals/001-journal.json", ctx())
    expect(denied(r)).toBe(".omp/evidence/journals/")
  })

  it("allows a normal nested path for writes", () => {
    const r = resolveWritePath("packages/app/src/util.ts", ctx())
    expect(ok(r)).toBe("packages/app/src/util.ts")
  })
})

import { describe, it, expect, beforeAll, afterAll } from "bun:test"
import { existsSync, rmSync, mkdirSync } from "node:fs"
import { resolve } from "node:path"
import { tmpdir } from "node:os"

describe("PGliteStore", () => {
  let tmpDir: string
  let store: import("../_lib/store/pglite-types.js").OmpRelationalStoreV1
  let skipTests = false

  beforeAll(async () => {
    tmpDir = resolve(tmpdir(), `omp-pglite-test-${Date.now()}`)
    mkdirSync(resolve(tmpDir, ".omp/state/pglite"), { recursive: true })

    try {
      const { getPgliteStore } = await import("../_lib/store/pglite-store.js")
      store = getPgliteStore({ repoRoot: tmpDir })
      await store.migrate()
    } catch {
      skipTests = true
    }
  })

  afterAll(() => {
    if (tmpDir && existsSync(tmpDir)) {
      rmSync(tmpDir, { recursive: true, force: true })
    }
  })

  // ── Idempotent Migration ──

  it("migrates idempotently", async () => {
    if (skipTests) return
    await store.migrate()
    await store.migrate()
  })

  // ── Actors ──

  it("creates and lists actors", async () => {
    if (skipTests) return
    const actor = await store.createActor({
      actor_id: "test-actor-1",
      kind: "agent",
      provider: "test",
      model: "test-model",
      display_name: "Test Actor",
    })
    expect(actor.actor_id).toBe("test-actor-1")
    expect(actor.kind).toBe("agent")
    expect(actor.provider).toBe("test")
    expect(actor.model).toBe("test-model")
    expect(actor.display_name).toBe("Test Actor")
    expect(actor.created_at).toBeDefined()
  })

  it("coerces unknown actor kind to 'unknown'", async () => {
    if (skipTests) return
    const actor = await store.createActor({
      actor_id: "test-actor-unknown",
      kind: "nonexistent_role",
    })
    expect(actor.kind).toBe("unknown")
  })

  // ── Sessions ──

  it("creates and heartbeats sessions", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-session", kind: "agent" })
    const session = await store.createSession({
      session_id: "session-heartbeat",
      actor_id: "a-session",
      purpose: "testing heartbeat",
    })
    expect(session.session_id).toBe("session-heartbeat")
    expect(session.actor_id).toBe("a-session")
    expect(session.status).toBe("active")
    expect(session.purpose).toBe("testing heartbeat")
    expect(session.started_at).toBeDefined()
    expect(session.last_heartbeat_at).toBeDefined()

    await store.heartbeatSession("session-heartbeat")
  })

  it("abandons expired sessions", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-expire", kind: "system" })
    await store.createSession({ session_id: "session-expire", actor_id: "a-expire" })

    // Set last_heartbeat to far in the past via direct SQL manipulation
    // The TTL is 30 minutes by default, so we need a past heartbeat
    // Since we can't directly manipulate, use abandonExpiredSessions with a future 'now'
    const futureNow = new Date(Date.now() + 31 * 60 * 1000) // 31 min in the future
    const report = await store.abandonExpiredSessions(futureNow)
    expect(report.abandoned_count).toBeGreaterThanOrEqual(1)
    expect(report.abandoned_session_ids).toContain("session-expire")
  })

  // ── Path Locks ──

  it("acquires and releases path locks", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-lock", kind: "agent" })
    await store.createSession({ session_id: "s-lock", actor_id: "a-lock" })

    const result = await store.acquirePathLocks({
      paths: [{ path: "src/test.ts", lock_kind: "write" }],
      session_id: "s-lock",
    })
    expect(result.acquired).toBe(true)
    expect(result.lock_ids).toBeDefined()
    expect(result.lock_ids!.length).toBe(1)

    await store.releasePathLocks({
      lock_ids: result.lock_ids!,
      session_id: "s-lock",
    })
  })

  it("refuses conflicting write locks", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-conflict", kind: "agent" })
    const s1 = await store.createSession({ session_id: "s-conflict-1", actor_id: "a-conflict" })
    const s2 = await store.createSession({ session_id: "s-conflict-2", actor_id: "a-conflict" })

    const r1 = await store.acquirePathLocks({
      paths: [{ path: "conflict-test.ts", lock_kind: "write" }],
      session_id: "s-conflict-1",
    })
    expect(r1.acquired).toBe(true)

    const r2 = await store.acquirePathLocks({
      paths: [{ path: "conflict-test.ts", lock_kind: "write" }],
      session_id: "s-conflict-2",
    })
    expect(r2.acquired).toBe(false)
    expect(r2.conflicts).toBeDefined()
    expect(r2.conflicts!.length).toBe(1)
    expect(r2.conflicts![0].path).toBe("conflict-test.ts")
    expect(r2.conflicts![0].owning_session_id).toBe("s-conflict-1")
  })

  it("allows concurrent read locks", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-concurrent-read", kind: "agent" })
    await store.createSession({ session_id: "s-read-1", actor_id: "a-concurrent-read" })
    await store.createSession({ session_id: "s-read-2", actor_id: "a-concurrent-read" })

    const r1 = await store.acquirePathLocks({
      paths: [{ path: "shared-read.ts", lock_kind: "read" }],
      session_id: "s-read-1",
    })
    expect(r1.acquired).toBe(true)

    // Second session can also get a read lock on the same path
    const r2 = await store.acquirePathLocks({
      paths: [{ path: "shared-read.ts", lock_kind: "read" }],
      session_id: "s-read-2",
    })
    expect(r2.acquired).toBe(true)
  })

  it("releases locks and allows re-acquisition", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-reacquire", kind: "agent" })
    await store.createSession({ session_id: "s-reacquire", actor_id: "a-reacquire" })

    const r1 = await store.acquirePathLocks({
      paths: [{ path: "reacquire.ts", lock_kind: "write" }],
      session_id: "s-reacquire",
    })
    expect(r1.acquired).toBe(true)

    await store.releasePathLocks({
      lock_ids: r1.lock_ids!,
      session_id: "s-reacquire",
    })

    // Now the same session can re-acquire
    const r2 = await store.acquirePathLocks({
      paths: [{ path: "reacquire.ts", lock_kind: "write" }],
      session_id: "s-reacquire",
    })
    expect(r2.acquired).toBe(true)
  })

  it("auto-expires locks after TTL", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-ttl", kind: "agent" })
    await store.createSession({ session_id: "s-ttl-1", actor_id: "a-ttl" })
    await store.createSession({ session_id: "s-ttl-2", actor_id: "a-ttl" })

    const r = await store.acquirePathLocks({
      paths: [{ path: "ephemeral.ts", lock_kind: "write" }],
      session_id: "s-ttl-1",
      ttl_ms: 100,
    })
    expect(r.acquired).toBe(true)

    await new Promise((resolve) => setTimeout(resolve, 150))

    // After TTL, a new session should be able to lock
    const r2 = await store.acquirePathLocks({
      paths: [{ path: "ephemeral.ts", lock_kind: "write" }],
      session_id: "s-ttl-2",
    })
    expect(r2.acquired).toBe(true)
  })

  // ── Invocations ──

  it("records invocations", async () => {
    if (skipTests) return
    await store.createActor({ actor_id: "a-invoke", kind: "agent" })
    await store.createSession({ session_id: "s-invoke", actor_id: "a-invoke" })

    await store.recordInvocation({
      invocation_id: "inv-1",
      session_id: "s-invoke",
      tool_id: "text_replace",
      tool_version: "1.0.0",
      status: "ok",
      risk_level: "low",
      started_at: new Date().toISOString(),
      finished_at: new Date().toISOString(),
      duration_ms: 42,
      input_sha256: "abc123",
    })
  })

  it("records error invocations", async () => {
    if (skipTests) return
    await store.recordInvocation({
      invocation_id: "inv-error",
      session_id: "s-invoke",
      tool_id: "text_replace",
      tool_version: "1.0.0",
      status: "error",
      risk_level: "medium",
      started_at: new Date().toISOString(),
      finished_at: new Date().toISOString(),
      duration_ms: 5,
      input_sha256: "def456",
      error_code: "E_PERMISSION",
      error_message: "Permission denied",
    })
  })

  // ── File Effects ──

  it("records mutations", async () => {
    if (skipTests) return
    await store.recordMutation({
      invocation_id: "inv-1",
      session_id: "s-invoke",
      path: "src/main.ts",
      action: "write",
      before_sha256: "aaa",
      after_sha256: "bbb",
      before_size_bytes: 100,
      after_size_bytes: 120,
    })
  })

  it("records an invocation and its mutations atomically", async () => {
    if (skipTests) return
    await store.recordInvocationWithMutations({
      invocation: {
        invocation_id: "inv-atomic",
        session_id: "s-invoke",
        tool_id: "text_replace",
        tool_version: "1.0.0",
        status: "ok",
        risk_level: "medium",
        started_at: new Date().toISOString(),
        finished_at: new Date().toISOString(),
        duration_ms: 1,
        input_sha256: "atomic-input",
      },
      mutations: [
        {
          invocation_id: "inv-atomic",
          session_id: "s-invoke",
          path: "src/atomic.ts",
          action: "write",
          before_sha256: "aaa",
          after_sha256: "bbb",
          before_size_bytes: 10,
          after_size_bytes: 12,
        },
      ],
    })

    const recent = await store.listRecentInvocations(5)
    expect(recent.some((i) => i.invocation_id === "inv-atomic")).toBe(true)

    const effects = await store.listEffectsForPath("src/atomic.ts")
    expect(effects.some((e) => e.invocation_id === "inv-atomic")).toBe(true)
  })

  it("records reads", async () => {
    if (skipTests) return
    await store.recordRead({
      invocation_id: "inv-1",
      session_id: "s-invoke",
      path: "src/readme.md",
      sha256: "readhash",
      size_bytes: 500,
    })
  })

  // ── Write Journals ──

  it("creates and commits write journals", async () => {
    if (skipTests) return
    await store.createWriteJournal({
      journal_id: "journal-1",
      invocation_id: "inv-1",
      session_id: "s-invoke",
      status: "prepared",
      journal_path: ".omp/tools/journals/journal-1.json",
    })

    await store.updateWriteJournalStatus({
      journal_id: "journal-1",
      status: "committed",
    })

    const pending = await store.findPendingJournals()
    expect(pending.find((j) => j.journal_id === "journal-1")).toBeUndefined()
  })

  it("finds pending journals", async () => {
    if (skipTests) return
    await store.createWriteJournal({
      journal_id: "journal-pending",
      invocation_id: "inv-1",
      session_id: "s-invoke",
      status: "prepared",
      journal_path: ".omp/tools/journals/journal-pending.json",
    })

    const pending = await store.findPendingJournals()
    expect(pending.some((j) => j.journal_id === "journal-pending")).toBe(true)
  })

  // ── Queries ──

  it("lists recent invocations", async () => {
    if (skipTests) return
    const recent = await store.listRecentInvocations(10)
    expect(recent.length).toBeGreaterThanOrEqual(1)
    const found = recent.find((i) => i.invocation_id === "inv-1")
    expect(found).toBeDefined()
    expect(found!.tool_id).toBe("text_replace")
    expect(found!.status).toBe("ok")
  })

  it("lists effects for path", async () => {
    if (skipTests) return
    const effects = await store.listEffectsForPath("src/main.ts")
    expect(effects.length).toBeGreaterThanOrEqual(1)
    const found = effects.find((e) => e.action === "write")
    expect(found).toBeDefined()
    expect(found!.session_id).toBe("s-invoke")
  })
})

import { describe, it, expect } from "bun:test"
import { readFileSync, existsSync } from "node:fs"
import { resolve } from "node:path"

const ROLES_DIR = resolve(import.meta.dir, "../../prompts/roles")
const WORKFLOWS_DIR = resolve(import.meta.dir, "../../prompts/workflows")
const SNIPPETS_DIR = resolve(import.meta.dir, "../../prompts/snippets")
const CONSTITUTION_PATH = resolve(import.meta.dir, "../../../AGENTS.md")

function readPromptFile(dir: string, file: string): string {
  const filepath = resolve(dir, file)
  if (!existsSync(filepath)) {
    throw new Error(`Prompt file does not exist: ${filepath}`)
  }
  return readFileSync(filepath, "utf8")
}

describe("OMP Prompt Suite Linter", () => {

  describe("AGENTS.md Constitution", () => {
    it("contains the core OMP constitutional constraints", () => {
      const content = readFileSync(CONSTITUTION_PATH, "utf8")
      expect(content).toContain("OMP Runtime Constitution")
      expect(content).toContain("PGlite database is the single source of truth")
      expect(content).toContain("derived analytical queries")
      expect(content).toContain("receipts")
      expect(content).toContain("transport")
    })

    it("requires code-intelligence-first context acquisition sequence", () => {
      const content = readFileSync(CONSTITUTION_PATH, "utf8")
      expect(content).toContain("Check Code-Index Snapshot")
      expect(content).toContain("Query Kernel First")
      expect(content).toContain("semantic_repo_map")
      expect(content).toContain("impact_analysis")
    })
  })

  describe("Role Prompts Validation", () => {
    const roles = ["implementer.md", "reviewer.md", "planner.md", "verifier.md", "exporter.md", "recovery.md"]

    it("ensures all roles require code-intelligence context lookup first", () => {
      for (const role of roles) {
        const content = readPromptFile(ROLES_DIR, role)
        const hasKernelLookup = content.toLowerCase().includes("code-intelligence") || content.toLowerCase().includes("kernel")
        expect(hasKernelLookup).toBe(true)
      }
    })

    it("ensures read-only roles explicitly prohibit mutation", () => {
      const readOnlyRoles = ["reviewer.md", "verifier.md", "exporter.md", "recovery.md"]
      for (const role of readOnlyRoles) {
        const content = readPromptFile(ROLES_DIR, role)
        const prohibitsMutation = content.toLowerCase().includes("prohibit") ||
                                  content.toLowerCase().includes("non-mutating") ||
                                  content.toLowerCase().includes("read-only") ||
                                  content.toLowerCase().includes("no auto-repair")
        expect(prohibitsMutation).toBe(true)
      }
    })

    it("ensures mutation roles require OMP write tools with locks, hashes, and receipts", () => {
      const content = readPromptFile(ROLES_DIR, "implementer.md")
      expect(content).toContain("text_replace")
      expect(content).toContain("batch_edit")
      expect(content).toContain("locks")
      expect(content).toContain("hash")
      expect(content).toContain("receipt")
    })

    it("ensures planner is restricted to drafts and campaign tools", () => {
      const content = readPromptFile(ROLES_DIR, "planner.md")
      expect(content).toContain("draft")
      expect(content).toContain("campaign")
    })

    it("ensures recovery role is forbidden from auto-repairing without explicit mission", () => {
      const content = readPromptFile(ROLES_DIR, "recovery.md")
      expect(content).toContain("No Auto-Repair")
      expect(content).toContain("repair mission")
    })
  })

  describe("Workflow Prompts Validation", () => {
    it("ensures unattended workflow includes stop conditions", () => {
      const content = readPromptFile(WORKFLOWS_DIR, "unattended_mission.md")
      expect(content).toContain("Stopping Gates")
    })

    it("ensures campaign completion requires consistency validation", () => {
      const content = readPromptFile(WORKFLOWS_DIR, "campaign_completion.md")
      expect(content).toContain("snapshot")
      expect(content).toContain("consistent")
    })

    it("ensures review packet triage inspects 10_review_findings.json directly", () => {
      const content = readPromptFile(WORKFLOWS_DIR, "review_packet_triage.md")
      expect(content).toContain("10_review_findings.json")
      expect(content).toContain("severity")
    })
  })
})

import { describe, it, expect } from "bun:test"
import { existsSync, readFileSync, rmSync, mkdirSync } from "node:fs"
import { resolve } from "node:path"
import { tmpdir } from "node:os"
import { allocateReceiptPath, buildReceipt, writeReceipt } from "../_lib/receipts"
import { buildToolContext } from "../_lib/tool-context"
import type { OmpToolContextV1, OmpToolReceiptV1 } from "../_lib/types"

// ── Test helpers ──

let testDir: string

function freshCtx(): OmpToolContextV1 {
  testDir = resolve(tmpdir(), `receipts-test-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`)
  mkdirSync(testDir, { recursive: true })
    return buildToolContext({ cwd: testDir, repoRoot: testDir })
}

function cleanup(): void {
  if (testDir && existsSync(testDir)) {
    rmSync(testDir, { recursive: true, force: true })
  }
}

const stubFiles: OmpToolReceiptV1["files"] = [
  { path: "src/main.ts", action: "read" },
]

function baseOpts(ctx: OmpToolContextV1, receiptPath: string) {
  return {
    receipt_id: "test-001",
    invocation_id: "inv-abc123",
    tool_id: "test-tool",
    tool_version: "1.0.0",
    ctx,
    input_sha256: "a".repeat(64),
    normalized_input_sha256: "b".repeat(64),
    files: stubFiles,
    summary: "test receipt",
    diff_paths: [],
    hash_precondition_satisfied: true,
    receipt_path: receiptPath,
  }
}

// ── allocateReceiptPath ──

describe("allocateReceiptPath", () => {
  it("returns a dated path under receipts_dir", () => {
    const ctx = freshCtx()
    try {
      const path = allocateReceiptPath("test-001", ctx)
      expect(path).toMatch(/evidence\/receipts\/\d{4}-\d{2}-\d{2}\/test-001\.json$/)
    } finally {
      cleanup()
    }
  })

  it("includes the current date in YYYY-MM-DD format", () => {
    const ctx = freshCtx()
    try {
      const now = new Date()
      const yyyymmdd =
        `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`
      const path = allocateReceiptPath("receipt-abc", ctx)
      expect(path).toContain(yyyymmdd)
    } finally {
      cleanup()
    }
  })
})

// ── buildReceipt ──

describe("buildReceipt", () => {
  it("populates all required fields", () => {
    const ctx = freshCtx()
    try {
      const receiptPath = "/tmp/some/receipt.json"
      const opts = baseOpts(ctx, receiptPath)
      const receipt = buildReceipt(opts)

      expect(receipt.schema).toBe("omp.tool.receipt.v1")
      expect(receipt.receipt_id).toBe("test-001")
      expect(receipt.invocation_id).toBe("inv-abc123")
      expect(receipt.tool_id).toBe("test-tool")
      expect(receipt.tool_version).toBe("1.0.0")
      expect(receipt.created_at).toBeTruthy()
      expect(typeof receipt.created_at).toBe("string")
      expect(receipt.cwd).toBe(ctx.cwd)
      expect(receipt.actor).toEqual(ctx.actor)
      expect(receipt.command.input_sha256).toBe(opts.input_sha256)
      expect(receipt.command.normalized_input_sha256).toBe(opts.normalized_input_sha256)
      expect(receipt.authority.risk_level).toBe("read")
      expect(receipt.authority.requires_hash_precondition).toBe(true)
      expect(receipt.authority.hash_precondition_satisfied).toBe(true)
      expect(receipt.authority.path_policy_satisfied).toBe(true)
      expect(receipt.files).toEqual(stubFiles)
      expect(receipt.result.status).toBe("ok")
      expect(receipt.result.summary).toBe("test receipt")
    } finally {
      cleanup()
    }
  })

  it("receipt_path in artifacts matches what was passed", () => {
    const ctx = freshCtx()
    try {
      const receiptPath = "/custom/path/receipt.json"
      const receipt = buildReceipt(baseOpts(ctx, receiptPath))
      expect(receipt.artifacts.receipt_path).toBe(receiptPath)
    } finally {
      cleanup()
    }
  })

  it("sets created_at to a valid ISO string", () => {
    const ctx = freshCtx()
    try {
      const receipt = buildReceipt(baseOpts(ctx, "/some/path.json"))
      const parsed = new Date(receipt.created_at)
      expect(parsed.getTime()).not.toBeNaN()
    } finally {
      cleanup()
    }
  })
})

// ── writeReceipt ──

describe("writeReceipt", () => {
  it("creates the receipt file on disk", () => {
    const ctx = freshCtx()
    try {
      const receiptPath = resolve(testDir, "evidence", "receipts", "test-001.json")
      const receipt = buildReceipt(baseOpts(ctx, receiptPath))
      writeReceipt(receipt, receiptPath)
      expect(existsSync(receiptPath)).toBe(true)
    } finally {
      cleanup()
    }
  })

  it("creates parent directories when they don't exist", () => {
    const ctx = freshCtx()
    try {
      const deepPath = resolve(testDir, "a", "b", "c", "receipt.json")
      const receipt = buildReceipt(baseOpts(ctx, deepPath))
      writeReceipt(receipt, deepPath)
      expect(existsSync(deepPath)).toBe(true)
    } finally {
      cleanup()
    }
  })

  it("written JSON is valid and matches the input receipt", () => {
    const ctx = freshCtx()
    try {
      const receiptPath = resolve(testDir, "receipt.json")
      const receipt = buildReceipt(baseOpts(ctx, receiptPath))
      writeReceipt(receipt, receiptPath)

      const raw = readFileSync(receiptPath, "utf8")
      const parsed: OmpToolReceiptV1 = JSON.parse(raw)
      expect(parsed.schema).toBe("omp.tool.receipt.v1")
      expect(parsed.receipt_id).toBe(receipt.receipt_id)
      expect(parsed.created_at).toBe(receipt.created_at)
      expect(parsed.artifacts.receipt_path).toBe(receiptPath)
      expect(parsed.result.summary).toBe("test receipt")
    } finally {
      cleanup()
    }
  })
})

import { describe, it, expect } from "bun:test"
import { validateStructReadInput } from "../_lib/schemas"
import { resolveReadPath } from "../_lib/path-policy"
import { buildToolContext } from "../_lib/tool-context"
import { sha256, fileSha256 } from "../_lib/hashing"
import { writeFileSync, mkdtempSync, rmSync } from "node:fs"
import { join } from "node:path"
import { tmpdir } from "node:os"

function ctx() {
  return buildToolContext({ cwd: "/tmp/test-repo" })
}

// ── validateStructReadInput ──

describe("validateStructReadInput", () => {
  it("accepts minimal valid input (just path)", () => {
    const r = validateStructReadInput({ path: "src/main.ts" })
    expect(r.ok).toBe(true)
    if (r.ok) {
      expect(r.value.path).toBe("src/main.ts")
    }
  })

  it("accepts focus mode with symbol_name", () => {
    const r = validateStructReadInput({ path: "src/main.ts", mode: "focus", symbol_name: "MyClass" })
    expect(r.ok).toBe(true)
    if (r.ok) {
      expect(r.value.mode).toBe("focus")
      expect(r.value.symbol_name).toBe("MyClass")
    }
  })

  it("accepts all valid modes", () => {
    const modes = ["full", "head", "range", "symbols", "focus"] as const
    for (const mode of modes) {
      const r = validateStructReadInput({ path: "src/main.ts", mode })
      expect(r.ok).toBe(true)
    }
  })

  it("rejects invalid mode", () => {
    const r = validateStructReadInput({ path: "src/main.ts", mode: "invalid" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/mode/)
    }
  })

  it("rejects invalid mode type (number)", () => {
    const r = validateStructReadInput({ path: "src/main.ts", mode: 42 })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/mode/)
    }
  })

  it("rejects missing path", () => {
    const r = validateStructReadInput({})
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/path/)
    }
  })

  it("rejects non-string path", () => {
    const r = validateStructReadInput({ path: 42 })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/path/)
    }
  })

  it("validates start_line type", () => {
    const r = validateStructReadInput({ path: "x.ts", start_line: "abc" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/start_line/)
    }
  })

  it("validates end_line type", () => {
    const r = validateStructReadInput({ path: "x.ts", end_line: "abc" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/end_line/)
    }
  })

  it("validates symbol_name type", () => {
    const r = validateStructReadInput({ path: "x.ts", symbol_name: 42 })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/symbol_name/)
    }
  })

  it("validates max_bytes type", () => {
    const r = validateStructReadInput({ path: "x.ts", max_bytes: "big" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/max_bytes/)
    }
  })

  it("validates max_lines type", () => {
    const r = validateStructReadInput({ path: "x.ts", max_lines: "lots" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/max_lines/)
    }
  })

  it("validates include_sha256 type", () => {
    const r = validateStructReadInput({ path: "x.ts", include_sha256: "yes" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/include_sha256/)
    }
  })

  it("validates include_line_numbers type", () => {
    const r = validateStructReadInput({ path: "x.ts", include_line_numbers: "yes" })
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/include_line_numbers/)
    }
  })

  it("accepts focus mode without symbol_name (no cross-field validation at schema level)", () => {
    // The schema validator checks individual field types but does not
    // cross-validate mode + symbol_name combinations. This test asserts
    // that the combination is accepted at the schema level; the actual
    // enforcement happens in the struct_read.ts handler at runtime.
    const r = validateStructReadInput({ path: "src/main.ts", mode: "focus" })
    // The validator accepts this structurally (no cross-field rule)
    expect(r.ok).toBe(true)
  })

  it("rejects non-object input", () => {
    const r = validateStructReadInput("not an object")
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/non-null object/)
    }
  })

  it("rejects null input", () => {
    const r = validateStructReadInput(null)
    expect(r.ok).toBe(false)
    if (!r.ok) {
      expect(r.error).toMatch(/non-null object/)
    }
  })

  it("accepts all optional fields with correct types", () => {
    const r = validateStructReadInput({
      path: "x.ts",
      mode: "range",
      start_line: 10,
      end_line: 20,
      symbol_name: "foo",
      max_bytes: 1024,
      max_lines: 50,
      include_sha256: true,
      include_line_numbers: false,
    })
    expect(r.ok).toBe(true)
  })
})

// ── Path policy (resolveReadPath) ──

describe("resolveReadPath path policy", () => {
  it("denies .env", () => {
    const r = resolveReadPath(".env", ctx())
    expect(r.ok).toBe(false)
    expect(r.denied_pattern).toBe(".env")
  })

  it("denies .env.* pattern", () => {
    const r = resolveReadPath(".env.production", ctx())
    expect(r.ok).toBe(false)
    expect(r.denied_pattern).toBe(".env.*")
  })

  it("denies *.pem files", () => {
    const r = resolveReadPath("secret.pem", ctx())
    expect(r.ok).toBe(false)
    expect(r.denied_pattern).toBe("*.pem")
  })

  it("denies *.key files", () => {
    const r = resolveReadPath("id_rsa.key", ctx())
    expect(r.ok).toBe(false)
    expect(r.denied_pattern).toBe("*.key")
  })

  it("allows normal .ts files", () => {
    const r = resolveReadPath("src/main.ts", ctx())
    expect(r.ok).toBe(true)
    if (r.ok) {
      expect(r.normalized_path).toBe("src/main.ts")
    }
  })

  it("allows normal nested .ts files", () => {
    const r = resolveReadPath("packages/app/src/utils.ts", ctx())
    expect(r.ok).toBe(true)
    if (r.ok) {
      expect(r.normalized_path).toBe("packages/app/src/utils.ts")
    }
  })
})

// ── sha256 ──

describe("sha256", () => {
  it("sha256 of a sample file matches expected", () => {
    const tmp = mkdtempSync(join(tmpdir(), "struct-read-test-"))
    try {
      const content = "hello world\n"
      const filePath = join(tmp, "sample.txt")
      writeFileSync(filePath, content, "utf-8")

      const fileHash = fileSha256(filePath)
      const expected = sha256(content)
      expect(fileHash).toBe(expected)
      expect(fileHash.length).toBe(64) // 256 bits = 64 hex chars
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })

  it("sha256 is deterministic", () => {
    const content = "consistent data\n"
    expect(sha256(content)).toBe(sha256(content))
  })

  it("sha256 produces 64-character hex string", () => {
    const hash = sha256("test data")
    expect(hash).toMatch(/^[0-9a-f]{64}$/)
  })
})

import { describe, it, expect } from "bun:test"
import { validateTextReplaceInput } from "../_lib/schemas"
import { resolveWritePath } from "../_lib/path-policy"
import { sha256 } from "../_lib/hashing"
import type { OmpToolContextV1 } from "../_lib/types"

function makeContext(overrides?: Partial<OmpToolContextV1>): OmpToolContextV1 {
  return {
    cwd: "/test/repo",
    repo_root: "/test/repo",
    mode: "loose",
    actor: { kind: "agent", session_id: "test" },
    limits: { max_file_bytes: 1048576, max_output_bytes: 1048576, max_files_touched: 100 },
    paths: {
      receipts_dir: "/test/repo/.omp/evidence/receipts",
      diffs_dir: "/test/repo/.omp/evidence/diffs",
      events_path: "/test/repo/.omp/evidence/events/events.jsonl",
      journals_dir: "/test/repo/.omp/evidence/journals",
    },
    ...overrides,
  }
}

describe("validateTextReplaceInput", () => {
  it("accepts valid input", () => {
    const result = validateTextReplaceInput({
      path: "src/main.ts",
      expected_before_sha256: "abc123",
      old_text: "foo",
      new_text: "bar",
    })
    expect(result.ok).toBe(true)
    if (result.ok) {
      expect(result.value.path).toBe("src/main.ts")
      expect(result.value.expected_before_sha256).toBe("abc123")
      expect(result.value.old_text).toBe("foo")
      expect(result.value.new_text).toBe("bar")
    }
  })

  it("rejects missing expected_before_sha256", () => {
    const result = validateTextReplaceInput({
      path: "src/main.ts",
      old_text: "foo",
      new_text: "bar",
    })
    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toContain("expected_before_sha256")
    }
  })

  it("rejects missing path", () => {
    const result = validateTextReplaceInput({
      expected_before_sha256: "abc",
      old_text: "foo",
      new_text: "bar",
    })
    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toContain("path")
    }
  })

  it("rejects missing old_text", () => {
    const result = validateTextReplaceInput({
      path: "src/main.ts",
      expected_before_sha256: "abc",
      new_text: "bar",
    })
    expect(result.ok).toBe(false)
    if (!result.ok) {
      expect(result.error).toContain("old_text")
    }
  })
})

describe("path policy — resolveWritePath", () => {
  const ctx = makeContext()

  it("denies .env", () => {
    const decision = resolveWritePath(".env", ctx)
    expect(decision.ok).toBe(false)
    if (!decision.ok) {
      expect(decision.denied_pattern).toBe(".env")
    }
  })

  it("denies parent directory traversal (../)", () => {
    const decision = resolveWritePath("../outside", ctx)
    expect(decision.ok).toBe(false)
    if (!decision.ok) {
      expect(decision.denied_pattern).toBe("<escape>")
    }
  })
})

describe("sha256", () => {
  it("produces a 64-character hex string", () => {
